class Solution {
public:
    int countSubranges(vector<int>& nums1, vector<int>& nums2) {
        const int MOD = 1000000007;
        unordered_map<int, int> dp;
        long long answer = 0;
        for (int i = 0; i < (int)nums1.size(); ++i) {
            unordered_map<int, int> next;
            auto add = [&](int diff, int count) {
                int& slot = next[diff];
                slot = (slot + count) % MOD;
            };
            add(nums1[i], 1);
            add(-nums2[i], 1);
            for (const auto& item : dp) {
                add(item.first + nums1[i], item.second);
                add(item.first - nums2[i], item.second);
            }
            dp.swap(next);
            answer = (answer + dp[0]) % MOD;
        }
        return (int)answer;
    }
};
